const aiResp = $input.first().json;
const prop = $('🔧 Parse Property Details').first().json;

let prompts = {};
try {
  const raw = aiResp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  prompts = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
} catch(e) {
  prompts = {
    instagram_image_prompt: `Photorealistic luxury ${prop.config} apartment interior, ${prop.location}, golden hour lighting, modern design, marble floors, panoramic windows, cinematic composition, 8K quality`,
    linkedin_image_prompt: `Premium real estate exterior, ${prop.location} skyline, architectural photography, sunset lighting, luxury residential building, professional composition`,
    instagram_caption: `✨ Dream home alert! ${prop.propertyTitle}\n📍 ${prop.location}\n💰 ${prop.price}\n\nContact us today!`,
    linkedin_caption: `Presenting an exceptional investment opportunity: ${prop.propertyTitle} at ${prop.price}. Prime ${prop.location} location.`
  };
}

return [{ json: { ...prop, prompts } }];

const instaResp = $('🎨 Gemini Image: Generate Instagram Visual').first().json;
const linkedinResp = $input.first().json;
const prop = $('🔀 Parse Image Prompts').first().json;
const prompts = prop.prompts || {};

// Extract Instagram image base64
let instaImageBase64 = null;
let instaImageMime = 'image/png';
try {
  const parts = instaResp?.candidates?.[0]?.content?.parts || [];
  for (const part of parts) {
    if (part.inlineData || part.inline_data) {
      const d = part.inlineData || part.inline_data;
      instaImageBase64 = d.data;
      instaImageMime = d.mimeType || 'image/png';
      break;
    }
  }
} catch(e) {}

// Extract LinkedIn image base64
let linkedinImageBase64 = null;
let linkedinImageMime = 'image/png';
try {
  const parts = linkedinResp?.candidates?.[0]?.content?.parts || [];
  for (const part of parts) {
    if (part.inlineData || part.inline_data) {
      const d = part.inlineData || part.inline_data;
      linkedinImageBase64 = d.data;
      linkedinImageMime = d.mimeType || 'image/png';
      break;
    }
  }
} catch(e) {}

const hasInsta = !!instaImageBase64;
const hasLinkedin = !!linkedinImageBase64;

// Build HTML email body
const c = {bg:'#0d1117',card:'#161b22',border:'#1e293b',orange:'#f97316',blue:'#2563eb',pink:'#ec4899',purple:'#8b5cf6',white:'#ffffff',light:'#e2e8f0',gray:'#94a3b8',green:'#22c55e',teal:'#0d9488'};

const emailBody = '<div style="background:'+c.bg+';padding:0;font-family:Segoe UI,Arial,sans-serif;max-width:650px;margin:0 auto;">' +
'<div style="background:linear-gradient(135deg,#ec4899 0%,#8b5cf6 100%);padding:28px 24px;text-align:center;border-radius:8px 8px 0 0;">' +
'<h1 style="margin:0;color:#fff;font-size:18px;font-weight:800;">🎨 AI-Generated Marketing Visuals</h1>' +
'<p style="margin:6px 0 0;color:#fce7f3;font-size:13px;">'+prop.propertyTitle+' | '+prop.price+'</p></div>' +
'<div style="background:'+c.card+';padding:20px;border:1px solid '+c.border+';border-top:none;border-radius:0 0 8px 8px;">' +
'<p style="color:'+c.light+';font-size:14px;margin:0 0 16px;">Hi '+prop.agentName+', your AI-generated property marketing visuals are ready. ' + (hasInsta || hasLinkedin ? 'Images are attached to this email.' : 'Image generation encountered an issue — please see captions below to retry manually.') + '</p>' +

'<div style="background:'+c.bg+';border-radius:8px;padding:14px;margin:0 0 16px;border-left:4px solid #ec4899;">' +
'<p style="color:#ec4899;font-size:13px;font-weight:700;margin:0 0 8px;">📸 INSTAGRAM VISUAL</p>' +
'<p style="color:'+c.gray+';font-size:11px;margin:0 0 8px;">Prompt used: '+( prompts.instagram_image_prompt || '' ).substring(0,120)+'...</p>' +
(hasInsta ? '<p style="color:'+c.green+';font-size:12px;margin:0 0 8px;">✅ Image attached as: Instagram_Visual_'+prop.propertyTitle.replace(/[^a-zA-Z0-9]/g,'_').substring(0,20)+'.png</p>' : '<p style="color:#ef4444;font-size:12px;margin:0 0 8px;">⚠️ Image generation failed — rate limit may have been hit. Retry manually.</p>') +
'<p style="color:'+c.gray+';font-size:10px;margin:0 0 6px;text-transform:uppercase;letter-spacing:1px;">INSTAGRAM CAPTION (copy-paste with the image):</p>' +
'<p style="color:'+c.light+';font-size:13px;line-height:1.6;margin:0;white-space:pre-wrap;">'+(prompts.instagram_caption || '').replace(/</g,'&lt;')+'</p></div>' +

'<div style="background:'+c.bg+';border-radius:8px;padding:14px;margin:0 0 16px;border-left:4px solid #0077b5;">' +
'<p style="color:#0077b5;font-size:13px;font-weight:700;margin:0 0 8px;">💼 LINKEDIN VISUAL</p>' +
'<p style="color:'+c.gray+';font-size:11px;margin:0 0 8px;">Prompt used: '+(prompts.linkedin_image_prompt || '').substring(0,120)+'...</p>' +
(hasLinkedin ? '<p style="color:'+c.green+';font-size:12px;margin:0 0 8px;">✅ Image attached as: LinkedIn_Visual_'+prop.propertyTitle.replace(/[^a-zA-Z0-9]/g,'_').substring(0,20)+'.png</p>' : '<p style="color:#ef4444;font-size:12px;margin:0 0 8px;">⚠️ Image generation failed — rate limit may have been hit. Retry manually.</p>') +
'<p style="color:'+c.gray+';font-size:10px;margin:0 0 6px;text-transform:uppercase;letter-spacing:1px;">LINKEDIN CAPTION (copy-paste with the image):</p>' +
'<p style="color:'+c.light+';font-size:13px;line-height:1.6;margin:0;white-space:pre-wrap;">'+(prompts.linkedin_caption || '').replace(/</g,'&lt;')+'</p></div>' +

'<div style="background:#f59e0b22;border-radius:6px;padding:10px 14px;margin:0;border:1px solid #f59e0b44;">' +
'<p style="color:#f59e0b;font-size:12px;margin:0;">💡 These are AI-generated concept visuals. Use them as teasers, mood boards, or "coming soon" posts while your professional photos are being shot.</p></div>' +
'</div></div>';

// Prepare binary attachments
const binaryData = {};

if (hasInsta) {
  binaryData['instagramVisual'] = {
    data: instaImageBase64,
    mimeType: instaImageMime,
    fileName: 'Instagram_Visual_' + prop.propertyTitle.replace(/[^a-zA-Z0-9]/g,'_').substring(0,25) + '.png',
    fileExtension: 'png'
  };
}

if (hasLinkedin) {
  binaryData['linkedinVisual'] = {
    data: linkedinImageBase64,
    mimeType: linkedinImageMime,
    fileName: 'LinkedIn_Visual_' + prop.propertyTitle.replace(/[^a-zA-Z0-9]/g,'_').substring(0,25) + '.png',
    fileExtension: 'png'
  };
}

return [{
  json: {
    agentEmail: prop.agentEmail,
    agentName: prop.agentName,
    propertyTitle: prop.propertyTitle,
    price: prop.price,
    emailBody,
    hasInsta,
    hasLinkedin
  },
  binary: binaryData
}];

const aiResp = $input.first().json;
const prop = $('🔧 Parse Property Details').first().json;

let kit = {};
try {
  const raw = aiResp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  kit = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
} catch (e) {
  kit = {
    portal_description_99acres: `${prop.config} ${prop.propertyType} for ${prop.transactionType} in ${prop.location}. ${prop.area}. ${prop.features}. ${prop.possession}. ${prop.furnishing}. Contact: ${prop.agentName} - ${prop.agentPhone}`,
    portal_description_short: `${prop.config} ${prop.propertyType} in ${prop.location}. ${prop.area}. ${prop.price}. ${prop.possession}. Call ${prop.agentPhone}`,
    portal_description_seo: `${prop.config} ${prop.propertyType} for ${prop.transactionType} in ${prop.location} at ${prop.price}. ${prop.features}. Contact ${prop.agentName}.`,
    instagram_caption: `🏠 ${prop.propertyTitle}\n📍 ${prop.location}\n💰 ${prop.price}\n📐 ${prop.area}\n\nDM for details!`,
    instagram_story_text: `🔥 ${prop.config} in ${prop.location} | ${prop.price} | DM Now!`,
    facebook_post: `${prop.propertyTitle}\n\n${prop.config} | ${prop.area} | ${prop.location}\nPrice: ${prop.price}\n${prop.features}\n\nContact: ${prop.agentName} - ${prop.agentPhone}`,
    whatsapp_broadcast: `🏠 *${prop.propertyTitle}*\n📍 ${prop.location}\n💰 ${prop.price}\n📐 ${prop.area}\n🏗 ${prop.possession}\n\n✅ ${prop.features}\n\n📞 ${prop.agentName} - ${prop.agentPhone}`,
    whatsapp_short: `${prop.config} | ${prop.location} | ${prop.price} | ${prop.agentPhone}`,
    broker_pitch: `Dear Partner, sharing an exclusive listing: ${prop.propertyTitle} at ${prop.price}. Contact for co-broking.`,
    neighbourhood_guide: `${prop.location} is a well-connected locality with excellent infrastructure.`,
    open_house_invite: prop.openHouseDate ? `You are invited to visit ${prop.propertyTitle} on ${prop.openHouseDate}.` : 'Open house date not scheduled.',
    buyer_followup_email_1: `Hi, thank you for your interest in ${prop.propertyTitle}. Would you like to schedule a visit?`,
    buyer_followup_email_2: `Hi, just checking in about ${prop.propertyTitle}. We have had other inquiries. Would you like to discuss further?`,
    buyer_followup_email_3: `Hi, wanted to follow up one last time about ${prop.propertyTitle}. No pressure at all.`,
    comparison_points: ['Prime location', 'Competitive pricing', 'Modern amenities', 'Good connectivity', 'Reputed builder'],
    objection_handling: [{objection: 'Price is too high', response: 'The price reflects premium amenities and location advantages.'}],
    price_justification: `This property is competitively priced for ${prop.location}.`,
    seo_keywords: [`${prop.config} in ${prop.location}`, `${prop.propertyType} for ${prop.transactionType} ${prop.location}`],
    target_audience_personas: [{persona: 'Working Professional', age: '28-40', income: '15-30 LPA', motivation: 'Upgrade to bigger space', where_to_find: 'LinkedIn, Instagram'}],
    owner_report_summary: `Your property at ${prop.location} has been listed and marketing has been activated across multiple channels.`
  };
}

return [{ json: { ...prop, kit } }];
